import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { toMigrations } from "./migrate.js";

// The SQL files are generated by drizzle-kit (`pnpm db:generate`). Vite bundles them as raw
// strings; plain Node (the `pnpm sm1` script) reads them from the folder instead.
function bundledMigrations(): {
  app: Record<string, string>;
  workspace: Record<string, string>;
} | null {
  try {
    // Vite replaces these calls at build time; plain Node has no `import.meta.glob` and throws.
    return {
      app: import.meta.glob("./migrations/app/*.sql", {
        query: "?raw",
        import: "default",
        eager: true,
      }) as Record<string, string>,
      workspace: import.meta.glob("./migrations/workspace/*.sql", {
        query: "?raw",
        import: "default",
        eager: true,
      }) as Record<string, string>,
    };
  } catch {
    return null;
  }
}

const bundled = bundledMigrations();

function fromDisk(folder: string): Record<string, string> {
  const directory = fileURLToPath(new URL(`./migrations/${folder}/`, import.meta.url));
  return Object.fromEntries(
    readdirSync(directory)
      .filter((name) => name.endsWith(".sql"))
      .map((name) => [name, readFileSync(join(directory, name), "utf8")]),
  );
}

export const appMigrations = toMigrations(bundled?.app ?? fromDisk("app"));
export const workspaceMigrations = toMigrations(bundled?.workspace ?? fromDisk("workspace"));
